DECLARE
  v_score INTEGER := 50;
  v_visits_count INTEGER;
  v_records_count INTEGER;
  v_recent_visits INTEGER;
BEGIN
  -- Count total visits
  SELECT COUNT(*) INTO v_visits_count
  FROM patient_visits
  WHERE patient_id = p_patient_id;

  -- Count medical records
  SELECT COUNT(*) INTO v_records_count
  FROM medical_records
  WHERE patient_id = p_patient_id;

  -- Count recent visits (last 6 months)
  SELECT COUNT(*) INTO v_recent_visits
  FROM patient_visits
  WHERE patient_id = p_patien

DECLARE
  v_score INTEGER := 50;
  v_customer customers;
BEGIN
  SELECT * INTO v_customer FROM customers WHERE id = p_customer_id;

  -- Recent activity bonus
  IF v_customer.last_contact_date > NOW() - INTERVAL '7 days' THEN
    v_score := v_score + 20;
  END IF;

  -- Lifecycle stage bonus
  CASE v_customer.lifecycle_stage
    WHEN 'prospect' THEN v_score := v_score + 10;
    WHEN 'customer' THEN v_score := v_score + 30;
    WHEN 'advocate' THEN v_score := v_score + 40;
    ELSE NULL;
  E

DECLARE
  conflict_count INTEGER;
BEGIN
  SELECT COUNT(*)
  INTO conflict_count
  FROM appointments
  WHERE doctor_id = p_doctor_id
    AND status IN ('scheduled', 'confirmed')
    AND appointment_date < p_appointment_date + INTERVAL '1 minute' * p_duration_minutes
    AND appointment_date + INTERVAL '1 minute' * 30 > p_appointment_date
    AND (p_exclude_appointment_id IS NULL OR id != p_exclude_appointment_id);

  RETURN conflict_count > 0;
END;

